func recipientColspan(canManage bool) string {
	if canManage {
		return "6"
	}
	return "5"
}

func orDefault(v string, fallback string) string {
	if v == "" {
		return fallback
	}
	return v
}

func orDash(v string) string {
	if v == "" {
		return "-"
	}
	return v
}

func invoiceListRecipient(email string) string {
	return orDash(email)
}

func recipientOptionSuffix(r services.InvoiceRecipient) string {
	if r.Email != "" {
		return " (" + r.Email + ")"
	}
	return ""
}

